// DATA-INTEGRITY-001v0.6§4: query echo corruption and valid foreign ownership differ.
integrityCase('public-revision-owner-query-contract',function(){assertSameValue(true,interface_exists(O\AssignmentOrderOriginalRevisionLineageRepository::class),'INTENDED_RED: revision-owner read seam');$m=(new ReflectionClass(O\AssignmentOrderOriginalRevisionLineageRepository::class))->getMethod('findLineageForRevision');assertSameValue('revisionId',$m->getParameters()[0]->getName(),'exact query argument');assertSameValue(O\AssignmentOrderOriginalLineageLookup::class,(string)$m->getReturnType(),'exact lookup return');});
$invalid=[
    'root-null'=>['root'=>null],'root-empty'=>['root'=>''],'root-query-mismatch'=>['root'=>'original-9999'],
    'revision-null'=>['revision'=>null],'revision-empty'=>['revision'=>''],'revision-slash'=>['revision'=>'bad/revision'],
    'number-null'=>['number'=>null],'number-zero'=>['number'=>0],'number-overflow'=>['number'=>4294967296],'number-count-mismatch'=>['number'=>2],
    'identity-null'=>['identity'=>null],'identity-arbitrary'=>['identity'=>'arbitrary'],'identity-order-mismatch'=>['identity'=>'composition-82-v1'],
    'hash-null'=>['hash'=>null],'hash-uppercase'=>['hash'=>str_repeat('A',64)],
    'date-null'=>['date'=>null],'date-invalid'=>['date'=>'2026-02-31'],'sha-null'=>['sha'=>null],'sha-invalid'=>['sha'=>str_repeat('A',64)],
    'case-null'=>['case'=>null],'case-zero'=>['case'=>0],'order-null'=>['order'=>null],'order-zero'=>['order'=>0],
    'empty-members'=>['ids'=>[]],'duplicate-members'=>['ids'=>['revision-0001','revision-0001']],
    'missing-current'=>['ids'=>['revision-0099']],'invalid-member'=>['ids'=>['bad/id','revision-0001'],'number'=>2],
    'non-list-members'=>['ids'=>[1=>'revision-0001']],'non-string-member'=>['ids'=>[42,'revision-0001'],'number'=>2],
    'current-not-last'=>['ids'=>['revision-0001','revision-0002'],'number'=>2], 'contradictory-membership'=>['contains'=>false],
    'not-found-payload'=>['status'=>O\AssignmentOrderOriginalLookupStatus::NOT_FOUND],
    'unavailable-payload'=>['status'=>O\AssignmentOrderOriginalLookupStatus::UNAVAILABLE],
];
foreach($invalid as $name=>$values)integrityCase('lineage-malformed-'.$name,function()use($values){$f=new S\OriginalIntegrityFixture(['correction'=>true,'lineage'=>new S\OriginalIntegrityLineage($values)]);integrityFailure($f,$f->run());assertSameValue([], $f->repository->revisionQueries,'malformed lineage never queries target owner');});
integrityCase('lineage-base-only-found',function(){$f=new S\OriginalIntegrityFixture(['correction'=>true,'lineage'=>new S\OriginalIntegrityIncompleteLineage()]);integrityFailure($f,$f->run());});
foreach(['status','root','revision','number','identity','hash','date','sha','case','order','ids','contains'] as $getter)integrityCase('lineage-getter-throw-'.$getter,function()use($getter){$f=new S\OriginalIntegrityFixture(['correction'=>true,'lineage'=>new S\OriginalIntegrityLineage([],$getter)]);integrityFailure($f,$f->run());});
integrityCase('lineage-valid-correction-control',function(){$v=new S\OriginalIntegrityLineage();$f=new S\OriginalIntegrityFixture(['correction'=>true,'lineage'=>$v]);$r=$f->run();assertSameValue(O\AssignmentOrderOriginalStatus::ACCEPTED,$r->status(),'complete current root accepted');assertSameValue(2,$r->revisionNumber(),'next revision');assertSameValue([], $f->repository->revisionQueries,'known current target no global query');foreach(['root','revision','number','identity','hash','date','sha','case','order','ids'] as $key)assertSameValue($f->repository->lineageCalls,$v->gets[$key]??0,'metadata once per lookup snapshot '.$key);});
foreach(['foreign-case'=>['case'=>9999],'foreign-order'=>['order'=>82,'identity'=>'composition-82-v1'],'different-composition'=>['identity'=>'composition-81-v2'],'different-hash'=>['hash'=>str_repeat('a',64)]] as $name=>$values)integrityCase('valid-root-semantic-'.$name,function()use($values){$f=new S\OriginalIntegrityFixture(['correction'=>true,'lineage'=>new S\OriginalIntegrityLineage($values)]);$r=$f->run();assertSameValue(['conflict','semantic_collision',false,$f->command->requestId,null,null,null,null,null,null,null],integrityTuple($r),'valid foreign metadata selects semantic collision');assertSameValue(0,$f->stream->readCalls,'semantic root drift before stream');assertSameValue(1,$f->stream->closeCalls,'semantic cleanup');assertSameValue(1,count($f->repository->attempts),'confirmed semantic terminal audit');assertSameValue([], $f->repository->revisionQueries,'no target query');});
integrityCase('root-not-found-semantic-control',function(){$f=new S\OriginalIntegrityFixture(['correction'=>true,'lineage'=>S\OriginalIntegrityLineage::absent()]);assertSameValue(O\AssignmentOrderOriginalReason::SEMANTIC_COLLISION,$f->run()->reasonCode(),'genuinely absent root semantic');assertSameValue(0,$f->stream->readCalls,'no root no stream');assertSameValue(1,count($f->repository->attempts),'persist selected conflict');});
integrityCase('root-unavailable-control',function(){$f=new S\OriginalIntegrityFixture(['correction'=>true,'lineage'=>S\OriginalIntegrityLineage::absent(O\AssignmentOrderOriginalLookupStatus::UNAVAILABLE)]);integrityFailure($f,$f->run());});
foreach(['missing','unavailable','echo-mismatch','malformed','valid'] as $kind)integrityCase('initial-CAS-lineage-'.$kind,function()use($kind){$line=match($kind){'missing'=>S\OriginalIntegrityLineage::absent(),'unavailable'=>S\OriginalIntegrityLineage::absent(O\AssignmentOrderOriginalLookupStatus::UNAVAILABLE),'echo-mismatch'=>new S\OriginalIntegrityLineage(['case'=>9999]),'malformed'=>new S\OriginalIntegrityLineage(['number'=>0]),default=>new S\OriginalIntegrityLineage()};$f=new S\OriginalIntegrityFixture(['acceptedOutcome'=>O\AssignmentOrderOriginalCommitStatus::CONFLICT,'assignmentLineages'=>[S\OriginalIntegrityLineage::absent(),$line]]);$r=$f->run();assertSameValue($kind==='valid'?['conflict','initial_already_exists',false]:['failed','persistence_failure',true],array_slice(integrityTuple($r),0,3),'initial conflict needs positive exact root evidence');assertSameValue(2,$f->repository->lineageCalls,'initial NF precheck then exact post-CAS reread');assertSameValue(1,$f->storage->stage->lease->releaseCalls,'release once after reclassification');assertSameValue([], $f->repository->accepted,'no accepted fact on conflict');assertSameValue($kind==='valid'?1:0,count($f->repository->attempts),'only confirmed business conflict terminal');});
$foreign=new S\OriginalIntegrityLineage(['root'=>'original-0099','revision'=>'revision-0099','ids'=>['revision-0099'],'case'=>9999,'order'=>82,'identity'=>'composition-82-v1']);
$ownerCases=[
    'globally-absent'=>[S\OriginalIntegrityLineage::absent(),'conflict','target_not_found'],
    'foreign-root'=>[$foreign,'conflict','semantic_collision'],
    'unavailable'=>[S\OriginalIntegrityLineage::absent(O\AssignmentOrderOriginalLookupStatus::UNAVAILABLE),'failed','persistence_failure'],
    'throw'=>[new RuntimeException('target lookup'),'failed','persistence_failure'],
    'base-only-found'=>[new S\OriginalIntegrityIncompleteLineage(),'failed','persistence_failure'],
    'missing-query-member'=>[new S\OriginalIntegrityLineage(['root'=>'original-0099','revision'=>'revision-0098','ids'=>['revision-0098']]),'failed','persistence_failure'],
    'same-root-contradiction'=>[new S\OriginalIntegrityLineage(['revision'=>'revision-0099','ids'=>['revision-0099']]),'failed','persistence_failure'],
    'malformed-owner'=>[new S\OriginalIntegrityLineage(['root'=>'original-0099','revision'=>'revision-0099','ids'=>['revision-0099'],'number'=>0]),'failed','persistence_failure'],
];
foreach($ownerCases as $name=>[$owner,$status,$reason])integrityCase('target-owner-'.$name,function()use($owner,$status,$reason){$f=new S\OriginalIntegrityFixture(['correction'=>true,'target'=>'revision-0099','revisionLineage'=>$owner]);$r=$f->run();assertSameValue([$status,$reason,$status==='failed'],array_slice(integrityTuple($r),0,3),'exact global target classification');assertSameValue(['revision-0099'],$f->repository->revisionQueries,'exactly one target-owner query');assertSameValue([], $f->repository->acceptedCalls,'no accepted commit');assertSameValue($status==='failed'?0:1,count($f->repository->attempts),'only business target conflict terminal');assertSameValue(0,$f->storage->stage->finalizeCalls,'normal target resolution before finalize');assertSameValue(null,$f->storage->stage->lease,'no lease acquired');assertSameValue(1,$f->storage->stage->abortCalls,'staged bytes aborted once');assertSameValue(1,$f->storage->stage->closeCalls,'stage closed once');assertSameValue(0,$f->ids->rootCalls+$f->ids->revisionCalls,'target checked before IDs');assertSameValue(1,$f->stream->closeCalls,'stream closed once');assertSameValue(0,$f->fresh->opens,'no commit outcome to recover');});
integrityCase('stale-expected-suppresses-target-query',function(){$f=new S\OriginalIntegrityFixture(['correction'=>true,'expected'=>'revision-0098','target'=>'revision-0099']);$r=$f->run();assertSameValue(O\AssignmentOrderOriginalReason::STALE_REVISION,$r->reasonCode(),'stale wins before target');assertSameValue([], $f->repository->revisionQueries,'no target query for stale expected');});
integrityCase('same-root-historical-target-control',function(){$line=new S\OriginalIntegrityLineage(['revision'=>'revision-0002','number'=>2,'ids'=>['revision-0001','revision-0002']]);$f=new S\OriginalIntegrityFixture(['correction'=>true,'expected'=>'revision-0002','lineage'=>$line]);assertSameValue(O\AssignmentOrderOriginalReason::TARGET_NOT_CURRENT,$f->run()->reasonCode(),'known historical target');assertSameValue([], $f->repository->revisionQueries,'known member requires no global query');});
foreach(['found','missing','unavailable','malformed','wrong-echo','without-interface'] as $kind)integrityCase('initial-precheck-'.$kind,function()use($kind){
    $line=match($kind){'found'=>new S\OriginalIntegrityLineage(),'unavailable'=>S\OriginalIntegrityLineage::absent(O\AssignmentOrderOriginalLookupStatus::UNAVAILABLE),'malformed'=>new S\OriginalIntegrityIncompleteLineage(),'wrong-echo'=>new S\OriginalIntegrityLineage(['case'=>9999]),default=>S\OriginalIntegrityLineage::absent()};
    $f=new S\OriginalIntegrityFixture(['assignmentLineage'=>$line,'withoutAssignment'=>$kind==='without-interface']);$r=$f->run();
    if($kind==='missing'){assertSameValue(O\AssignmentOrderOriginalStatus::ACCEPTED,$r->status(),'valid initial absence permits commit');assertSameValue(1,$f->repository->lineageCalls,'initial absence read once');}
    else{assertSameValue($kind==='found'?['conflict','initial_already_exists',false]:['failed','persistence_failure',true],array_slice(integrityTuple($r),0,3),'initial precheck exact outcome');assertSameValue(0,$f->storage->stage->finalizeCalls,'precheck before finalize');assertSameValue(0,$f->ids->rootCalls+$f->ids->revisionCalls,'precheck before IDs');assertSameValue([], $f->repository->acceptedCalls,'precheck no accepted commit');assertSameValue($kind==='found'?1:0,count($f->repository->attempts),'only proven existing original is terminal');assertSameValue(1,$f->storage->stage->abortCalls,'precheck cleanup');}
});
integrityCase('target-owner-interface-missing',function(){$f=new S\OriginalIntegrityFixture(['correction'=>true,'target'=>'revision-0099','withoutRevision'=>true]);$r=$f->run();assertSameValue(['failed','persistence_failure',true],array_slice(integrityTuple($r),0,3),'missing target-owner query is not absence');assertSameValue(0,$f->storage->stage->finalizeCalls,'missing query before finalize');assertSameValue([], $f->repository->attempts,'no false target-not-found terminal');});
foreach(['unchanged','stale','omitted-current','foreign-echo','unavailable'] as $kind)integrityCase('correction-post-CAS-'.$kind,function()use($kind){
    $last=match($kind){'stale'=>new S\OriginalIntegrityLineage(['revision'=>'revision-0002','number'=>2,'ids'=>['revision-0001','revision-0002'],'date'=>'2026-09-02']), 'omitted-current'=>new S\OriginalIntegrityLineage(['ids'=>['revision-0099']]),'foreign-echo'=>new S\OriginalIntegrityLineage(['root'=>'original-0099']), 'unavailable'=>S\OriginalIntegrityLineage::absent(O\AssignmentOrderOriginalLookupStatus::UNAVAILABLE), default=>new S\OriginalIntegrityLineage()};
    $f=new S\OriginalIntegrityFixture(['correction'=>true,'acceptedOutcome'=>O\AssignmentOrderOriginalCommitStatus::CONFLICT,'lineages'=>[new S\OriginalIntegrityLineage(),new S\OriginalIntegrityLineage(),$last]]);$r=$f->run();
    assertSameValue($kind==='stale'?['conflict','stale_revision',false]:['failed','persistence_failure',true],array_slice(integrityTuple($r),0,3),'reachable post-CAS cause proof');assertSameValue(1,count($f->repository->acceptedCalls),'one attempted CAS');assertSameValue([], $f->repository->accepted,'no accepted fact');assertSameValue([], $f->repository->revisionQueries,'no impossible post-CAS global target query');assertSameValue(1,$f->storage->stage->lease->releaseCalls,'post-CAS lease release once');assertSameValue($kind==='stale'?1:0,count($f->repository->attempts),'only proven stale is terminal');
});
foreach(['stale','historical','no-change'] as $kind)integrityCase('normal-step11-no-finalize-'.$kind,function()use($kind){
    $options=['correction'=>true];
    if($kind==='stale')$options['expected']='revision-0099';
    elseif($kind==='historical'){$options['expected']='revision-0002';$options['lineage']=new S\OriginalIntegrityLineage(['revision'=>'revision-0002','number'=>2,'ids'=>['revision-0001','revision-0002']]);}
    else $options['date']='2026-09-01';
    $f=new S\OriginalIntegrityFixture($options);$r=$f->run();$reason=match($kind){'stale'=>O\AssignmentOrderOriginalReason::STALE_REVISION,'historical'=>O\AssignmentOrderOriginalReason::TARGET_NOT_CURRENT,default=>O\AssignmentOrderOriginalReason::NO_CHANGES};
    assertSameValue($reason,$r->reasonCode(),'normal exact business reason');assertSameValue(0,$f->storage->stage->finalizeCalls,'step11 precedes finalize');assertSameValue(null,$f->storage->stage->lease,'no lease for selected rejection');assertSameValue(0,$f->ids->rootCalls+$f->ids->revisionCalls,'no allocated IDs');assertSameValue(1,$f->storage->stage->abortCalls,'staged bytes aborted');assertSameValue(1,$f->storage->stage->closeCalls,'stage closed once');assertSameValue(1,$f->stream->closeCalls,'stream closed once');assertSameValue(1,count($f->repository->attempts),'terminal/audit once');assertSameValue([], $f->repository->acceptedCalls,'no accepted write');
});
integrityCase('fingerprint-replay-precedes-stale-target',function(){
    $line=new S\OriginalIntegrityLineage(['revision'=>'revision-0002','number'=>2,'ids'=>['revision-0001','revision-0002'],'date'=>'2026-09-02']);
    $winner=new S\OriginalIntegrityResult(['request'=>'00000000-0000-4000-8000-000000000999','revision'=>'revision-0002','number'=>2,'date'=>'2026-09-02']);
    $f=new S\OriginalIntegrityFixture(['correction'=>true,'lineage'=>$line,'fingerprint'=>new S\OriginalIntegrityLookup(O\AssignmentOrderOriginalLookupStatus::FOUND,$winner)]);$r=$f->run();
    assertSameValue(O\AssignmentOrderOriginalStatus::REPLAYED,$r->status(),'winner replay precedes stale expected');assertSameValue(2,$r->revisionNumber(),'winner evidence');assertSameValue([], $f->repository->revisionQueries,'no target owner query');assertSameValue(0,$f->storage->stage->finalizeCalls,'no finalize on fingerprint winner');assertSameValue([], $f->repository->attempts,'no loser terminal audit');
});
integrityCase('correction-post-CAS-fingerprint-winner',function(){
    $winner=new S\OriginalIntegrityResult(['request'=>'00000000-0000-4000-8000-000000000999','revision'=>'revision-0002','number'=>2,'date'=>'2026-09-02']);
    $f=new S\OriginalIntegrityFixture(['correction'=>true,'acceptedOutcome'=>O\AssignmentOrderOriginalCommitStatus::CONFLICT,'fingerprints'=>[new S\OriginalIntegrityLookup(O\AssignmentOrderOriginalLookupStatus::NOT_FOUND),new S\OriginalIntegrityLookup(O\AssignmentOrderOriginalLookupStatus::FOUND,$winner)]]);$r=$f->run();
    assertSameValue(O\AssignmentOrderOriginalStatus::REPLAYED,$r->status(),'racing identical correction replays');assertSameValue(1,count($f->repository->acceptedCalls),'one CAS attempt');assertSameValue([], $f->repository->accepted,'no loser accepted fact');assertSameValue([], $f->repository->attempts,'no loser terminal');assertSameValue([], $f->repository->revisionQueries,'no global owner query after winner');assertSameValue(1,$f->storage->stage->lease->releaseCalls,'release after winner snapshot');assertSameValue(0,$f->observers->deliveryCalls,'loser replay no commit callback');
});
integrityDone('ASSIGNMENT_ORDER_ORIGINAL_DATA_LINEAGE_OK');
